func TestHIP3PublicSnapshotKnownAssetIDs(t *testing.T) {
	var fixture struct {
		Registry json.RawMessage            `json:"registry"`
		Metas    map[string]json.RawMessage `json:"metas"`
	}
	if err := json.Unmarshal([]byte(publicRoutingSnapshot), &fixture); err != nil {
		t.Fatal(err)
	}
	actions := make(chan int, 16)
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/info" {
			var q map[string]string
			if err := json.NewDecoder(r.Body).Decode(&q); err != nil {
				t.Error(err)
				return
			}
			switch q["type"] {
			case "meta":
				w.Write(fixture.Metas[q["dex"]])
			case "perpDexs":
				w.Write(fixture.Registry)
			default:
				t.Errorf("unexpected query %v", q)
			}
			return
		}
		if r.URL.Path != "/exchange" {
			t.Errorf("unexpected path %s", r.URL.Path)
			return
		}
		var e struct {
			Action struct {
				Orders []struct {
					Asset int `json:"a"`
				} `json:"orders"`
			} `json:"action"`
		}
		if err := json.NewDecoder(r.Body).Decode(&e); err != nil {
			t.Error(err)
			return
		}
		if len(e.Action.Orders) != 1 {
			t.Error("expected single order")
			return
		}
		actions <- e.Action.Orders[0].Asset
		fmt.Fprint(w, `{"status":"ok","response":{"type":"order","data":{"statuses":[{"resting":{"oid":1}}]}}}`)
	}))
	defer srv.Close()
	c, err := New(context.Background(), Config{BaseURL: srv.URL, AgentKey: testAgentKey, Account: testAccount, PerpDexs: []string{"para", "xyz", "io"}})
	if err != nil {
		t.Fatal(err)
	}
	for _, tc := range []struct {
		coin  string
		asset int
	}{
		{"io:ANTH", 200001}, {"xyz:JP225", 110044}, {"para:ANSEM", 180025}, {"para:10Y", 180015},
		{"XAI", 103}, {"para:TREAD", 180034}, {"xyz:CVX", 110120}, {"para:SMCI", 180024},
	} {
		if _, err := c.Place(context.Background(), []Order{{Coin: tc.coin, Px: "100", Sz: "1", Tif: TifAlo}}); err != nil {
			t.Fatalf("%s: %v", tc.coin, err)
		}
		if got := <-actions; got != tc.asset {
			t.Errorf("%s asset=%d want %d", tc.coin, got, tc.asset)
		}
	}
}
